<script>
  import { base } from '$app/paths';
  import { page } from '$app/stores';
  import { onMount } from 'svelte';
  let state={config:{repositories:[],apps:[],integrations:[],githubAccounts:[],publicHost:'',notifications:{},updateChecks:{interval:86400,lastCheck:null}},status:{},catalog:[],queue:{active:null,pending:[],count:0}};
  let githubRepos=[], accountId='', githubToken='', connectingGitHub=false, loadingRepos=false, repoLoadMessage='', repository='', publicRepository='', repoDialog=false, repoMode='public';
  let haNotifications={connected:false,notifyServices:[]};
  let message='', failure='';
  $: view=$page.url.pathname.replace(base,'').split('/').filter(Boolean)[0]||'dashboard';
  $: officialRepos=state.config.repositories.filter(repo=>repo.official);
  $: installedAppIds=new Set(state.config.apps.map(app=>app.id));
  $: officialApplications=[...new Map(officialRepos.flatMap(repo=>(repo.applications||[]).filter(app=>!installedAppIds.has(app.id)).map(app=>[app.id,{...app,kind:'application',repository:repo.fullName,source:repo.fullName}]))).values()];
  $: externalApplications=state.config.repositories.filter(repo=>!repo.official).flatMap(repo=>(repo.applications||[]).filter(app=>!installedAppIds.has(app.id)).map(app=>({...app,kind:'application',repository:repo.fullName,source:repo.fullName})));
  $: installedIntegrationItems=state.config.integrations.filter(item=>item.installed);
  $: availableIntegrationItems=state.config.integrations.filter(item=>!item.installed);
  $: officialIntegrations=availableIntegrationItems.filter(item=>state.config.repositories.some(repo=>repo.official&&repo.fullName===item.repository)).map(item=>({...item,kind:'integration',source:item.repository}));
  $: externalIntegrations=availableIntegrationItems.filter(item=>!state.config.repositories.some(repo=>repo.official&&repo.fullName===item.repository)).map(item=>({...item,kind:'integration',source:item.repository}));
  $: official=[...officialApplications,...officialIntegrations];
  $: external=[...externalApplications,...externalIntegrations];
  $: availableApplicationItems=state.config.repositories.flatMap(repo=>(repo.applications||[]).filter(app=>!installedAppIds.has(app.id)).map(app=>({...app,source:repo.fullName})));
  async function api(path,options={}){const response=await fetch(`${base}/api/${path}`,{headers:{'Content-Type':'application/json'},...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||data.error||`HTTP ${response.status}`);return data}
  async function refresh(){const [platform,queue]=await Promise.all([api('state'),api('queue')]);state={...platform,queue}}
  async function run(fn,text='Saved'){failure='';try{await fn();message=text;await refresh()}catch(error){failure=error.message}}
  onMount(()=>{refresh();api('ha/notifications').then(value=>haNotifications=value).catch(()=>{});const timer=setInterval(refresh,3000);return()=>clearInterval(timer)});
  async function addRepo(fullName=repository,selectedAccount=accountId){repoDialog=false;await run(()=>api('repositories',{method:'POST',body:JSON.stringify({fullName,accountId:selectedAccount})}),'Repository added and scan queued.')}
  async function scanAllRepositories(){await run(()=>api('repositories',{method:'POST',body:JSON.stringify({scanAll:true})}),`Scan / Git pull queued for ${state.config.repositories.length} repositories.`)}
  async function removeRepo(event,fullName){event.stopPropagation();if(!confirm(`Remove ${fullName} from X Platform? Installed integrations remain managed.`))return;await run(()=>api('repositories',{method:'DELETE',body:JSON.stringify({fullName})}),'Repository removed.')}
  async function loadRepos(){
    failure='';repoLoadMessage='';githubRepos=[];
    if(!accountId){failure='Choose a connected GitHub account first.';return}
    loadingRepos=true;
    try {
      githubRepos=await api(`github?account=${encodeURIComponent(accountId)}`);
      const privateCount=githubRepos.filter(repo=>repo.private).length;
      repoLoadMessage=githubRepos.length?`${githubRepos.length} repositories found (${privateCount} private).`:'GitHub returned no repositories for this token. Check repository selection and organization approval in the token settings.';
    } catch(error) { failure=error.message;repoLoadMessage='GitHub repository loading failed.'; }
    finally { loadingRepos=false; }
  }
  async function connectGitHub(){
    failure='';message='';connectingGitHub=true;
    try {
      const token=githubToken.trim();
      if(!token)throw new Error('Enter a fine-grained GitHub personal access token first.');
      const result=await api('github/pat',{method:'POST',body:JSON.stringify({token})});
      githubToken='';accountId=result.account.id;await refresh();await loadRepos();
      message=`GitHub connected as ${result.account.login}. ${repoLoadMessage}`;
    } catch(error) { failure=error.message; }
    finally { connectingGitHub=false; }
  }
  function counts(repo){return `${repo.integrations?.length||0} integrations · ${repo.applications?.length||0} applications`}
  function detected(repo){return (repo.integrations?.length||0)+(repo.applications?.length||0)}
  function repositoryUpdates(repo){const integrationUpdates=state.config.integrations.filter(item=>item.repository===repo.fullName&&item.installed&&item.stagedVersion&&item.installedVersion!==item.stagedVersion).length;const applicationUpdates=state.config.apps.filter(app=>app.repository===repo.fullName&&state.status[app.id]?.updateAvailable).length;return integrationUpdates+applicationUpdates}
  function asset(item,kind){const repository=item.repository||item.source;return item?.[kind]&&repository?`${base}/api/assets?repository=${encodeURIComponent(repository)}&path=${encodeURIComponent(item[kind])}`:''}
  function logoAsset(item){return asset(item,'logo')||asset(item,'icon')}
  async function saveNotifications(){await run(()=>api('settings',{method:'PUT',body:JSON.stringify({notifications:state.config.notifications})}),'Notification preferences saved.')}
  async function saveUpdateInterval(){await run(()=>api('settings',{method:'PUT',body:JSON.stringify({updateChecks:state.config.updateChecks})}),'Update check schedule saved.')}
  function toggleService(service){const selected=state.config.notifications.notifyServices||[];state.config.notifications.notifyServices=selected.includes(service)?selected.filter(item=>item!==service):[...selected,service];state={...state}}
  $: running=state.config.apps.filter(app=>state.status[app.id]?.state==='running').length;
  $: broken=state.config.apps.filter(app=>state.status[app.id]?.state==='error').length;
  $: installedIntegrations=state.config.integrations.filter(item=>item.installed).length;
  $: availableUpdates=state.config.integrations.filter(item=>item.installed&&item.stagedVersion&&item.installedVersion!==item.stagedVersion).length+state.config.apps.filter(item=>state.status[item.id]?.updateAvailable).length;
</script>
  {#if message}<div class="flash">{message}</div>{/if}{#if failure}<div class="flash bad">{failure}</div>{/if}
  {#if view==='dashboard'}
    {#if availableUpdates}<div class="update-banner"><b>{availableUpdates} update{availableUpdates===1?'':'s'} available</b><span>Review integrations and applications before installing.</span></div>{/if}
    <section class="metrics"><article><small>Applications</small><b>{running}<i> / {state.config.apps.length}</i></b><p>currently running</p></article><article><small>Integrations</small><b>{installedIntegrations}<i> / {state.config.integrations.length}</i></b><p>installed and managed</p></article><article><small>Repositories</small><b>{state.config.repositories.length}</b><p>connected sources</p></article><article class:metric-danger={broken>0}><small>Errors</small><b>{broken}</b><p>applications need attention</p></article></section>
    <div class="dashboard-grid"><section><h2>Application overview</h2><div class="table"><table><thead><tr><th>Application</th><th>Status</th><th>Port</th></tr></thead><tbody>{#each state.config.apps as app}<tr on:click={()=>location.href=`${base}/application?id=${encodeURIComponent(app.id)}`}><td><b>{app.name}</b></td><td><span class:ok={state.status[app.id]?.state==='running'}>{state.status[app.id]?.state||'stopped'}</span></td><td>{app.port}</td></tr>{:else}<tr><td colspan="3" class="empty">Install your first application from Discover.</td></tr>{/each}</tbody></table></div></section><section><h2>Repository overview</h2><div class="table"><table><thead><tr><th>Repository</th><th>Detected</th><th>Scanned</th></tr></thead><tbody>{#each state.config.repositories as repo}<tr on:click={()=>location.href=`${base}/repository?id=${encodeURIComponent(repo.fullName)}`}><td><b>{repo.fullName}</b></td><td>{detected(repo)}</td><td>{repo.scannedAt?new Date(repo.scannedAt).toLocaleString():'Not scanned yet'}</td></tr>{:else}<tr><td colspan="3" class="empty">No repositories added yet.</td></tr>{/each}</tbody></table></div></section></div>
  {:else if view==='discover'}
    {#if official.length}<h2>Official collection</h2><section class="poster-grid">{#each official as item}<a href={item.kind==='integration'?`${base}/integration?id=${encodeURIComponent(item.id)}`:`${base}/application?id=${item.id}&repository=${encodeURIComponent(item.source)}`}><div class="poster" class:has-image={asset(item,'background')} style:background-image={asset(item,'background')?`linear-gradient(0deg,#090c12cc,#090c1222),url('${asset(item,'background')}')`:''}>{#if logoAsset(item)}<img src={logoAsset(item)} alt={`${item.name} logo`}/>{:else}<span>{item.name.slice(0,1)}</span>{/if}<small>OFFICIAL</small></div><h3>{item.name}</h3><p>{item.description||item.repository}</p><div><span>{item.kind==='integration'?'Integration':'Application'}</span>{#if item.kind==='application'}<span>Port {item.port}</span>{:else}<span>{item.version||'Version not set'}</span>{/if}</div></a>{/each}</section>
    {/if}
    {#if external.length}<h2>From your repositories</h2><section class="poster-grid compact">{#each external as item}<a href={item.kind==='integration'?`${base}/integration?id=${encodeURIComponent(item.id)}`:`${base}/application?id=${item.id}&repository=${encodeURIComponent(item.source)}`}><div class="poster external" class:has-image={asset(item,'background')} style:background-image={asset(item,'background')?`linear-gradient(0deg,#090c12cc,#090c1222),url('${asset(item,'background')}')`:''}>{#if logoAsset(item)}<img src={logoAsset(item)} alt={`${item.name} logo`}/>{:else}<span>{item.name?.slice(0,1)||'X'}</span>{/if}<small>EXTERNAL</small></div><h3>{item.name}</h3><p>{item.source}</p><div><span>{item.kind==='integration'?'Integration':'Application'}</span><span>{item.kind==='integration'?(item.version||'Version not set'):(item.port||'Port not set')}</span></div></a>{/each}</section>{/if}
  {:else if view==='repositories'}
    <div class="toolbar"><button class="primary" on:click={()=>repoDialog=true}>+ Add repository</button><button disabled={!state.config.repositories.length} on:click={scanAllRepositories}>Scan / Git pull all</button></div>
    <div class="table"><table><thead><tr><th>Repository</th><th>Detected</th><th>Updates found</th><th>Scanned</th><th></th></tr></thead><tbody>{#each state.config.repositories as repo}{@const updates=repositoryUpdates(repo)}<tr on:click={()=>location.href=`${base}/repository?id=${encodeURIComponent(repo.fullName)}`}><td><b>https://github.com/{repo.fullName}.git {#if repo.official}<em>Official</em>{/if}</b></td><td>{counts(repo)}</td><td><span class:ok={updates>0}>{updates}</span></td><td>{repo.scannedAt?new Date(repo.scannedAt).toLocaleString():'Not scanned yet'}</td><td><button class="remove" on:click={(event)=>removeRepo(event,repo.fullName)}>Remove</button></td></tr>{:else}<tr><td colspan="5" class="empty">No repositories added.</td></tr>{/each}</tbody></table></div>
  {:else if view==='integrations'}
    {#if installedIntegrationItems.length}<h2>Downloaded integrations</h2><div class="table"><table><thead><tr><th>Integration</th><th>Path</th><th>Version</th><th>Last change</th><th>Repository</th></tr></thead><tbody>{#each installedIntegrationItems as item}<tr on:click={()=>location.href=`${base}/integration?id=${encodeURIComponent(item.id)}`}><td><b>{item.name}</b><small>{item.domain}</small></td><td>{item.path}</td><td><b>{item.installedVersion||'—'}</b>{#if item.stagedVersion&&item.stagedVersion!==item.installedVersion}<span class="version-arrow">➜</span><b class="new-version">{item.stagedVersion}</b>{/if}</td><td>{item.installedAt?new Date(item.installedAt).toLocaleString():'—'}</td><td>{item.repository}</td></tr>{/each}</tbody></table></div>{/if}{#if availableIntegrationItems.length}<h2>Available integrations</h2><div class="table"><table><thead><tr><th>Integration</th><th>Path</th><th>Version</th><th>Repository</th></tr></thead><tbody>{#each availableIntegrationItems as item}<tr on:click={()=>location.href=`${base}/integration?id=${encodeURIComponent(item.id)}`}><td><b>{item.name}</b><small>{item.domain}</small></td><td>{item.path}</td><td>{item.version||'—'}</td><td>{item.repository}</td></tr>{/each}</tbody></table></div>{/if}{#if !state.config.integrations.length}<div class="table empty">No integrations detected.</div>{/if}
  {:else if view==='applications'}
    {#if state.config.apps.length}<h2>Downloaded applications</h2><div class="table"><table><thead><tr><th>Application</th><th>Status</th><th>Repository</th><th>Version</th><th>Port</th><th>Last change</th></tr></thead><tbody>{#each state.config.apps as app}{@const appStatus=state.status[app.id]||{}}<tr on:click={()=>location.href=`${base}/application?id=${encodeURIComponent(app.id)}`}><td><b>{app.name}</b></td><td><span class="app-state" class:running={appStatus.state==='running'} class:error={appStatus.state==='error'} class:busy={appStatus.state==='installing'||appStatus.state==='updating'}>{appStatus.state||'stopped'}</span></td><td>{app.repository}</td><td><b>{appStatus.installedVersion||app.version||'—'}</b>{#if appStatus.availableVersion&&appStatus.availableVersion!==(appStatus.installedVersion||app.version)}<span class="version-arrow">➜</span><b class="new-version">{appStatus.availableVersion}</b>{/if}</td><td>{app.port}</td><td>{appStatus.updatedAt?new Date(appStatus.updatedAt).toLocaleString():'—'}</td></tr>{/each}</tbody></table></div>{/if}{#if availableApplicationItems.length}<h2>Available applications</h2><div class="table"><table><thead><tr><th>Application</th><th>Repository</th><th>Version</th><th>Port</th><th>Last change</th></tr></thead><tbody>{#each availableApplicationItems as app}<tr on:click={()=>location.href=`${base}/application?id=${encodeURIComponent(app.id)}&repository=${encodeURIComponent(app.source)}`}><td><b>{app.name}</b></td><td>{app.source}</td><td>{app.version||'—'}</td><td>{app.port||'—'}</td><td>—</td></tr>{/each}</tbody></table></div>{/if}{#if !state.config.apps.length&&!availableApplicationItems.length}<div class="table empty">No applications detected.</div>{/if}
  {:else if view==='queued'}
    <h2>Active</h2><div class="table"><table><thead><tr><th>Task</th><th>Target</th><th>Started</th></tr></thead><tbody>{#if state.queue.active}{@const task=state.queue.active}<tr><td><b>{task.type}</b></td><td>{task.appId||task.integrationId||task.repository||'X Platform'}</td><td>{task.startedAt?new Date(task.startedAt).toLocaleString():'—'}</td></tr>{:else}<tr><td colspan="3" class="empty">Nothing is running.</td></tr>{/if}</tbody></table></div>
    <h2>Waiting</h2><div class="table"><table><thead><tr><th>Task</th><th>Target</th><th>Queued</th></tr></thead><tbody>{#each state.queue.pending||[] as task}<tr><td><b>{task.type}</b></td><td>{task.appId||task.integrationId||task.repository||'X Platform'}</td><td>{task.createdAt?new Date(task.createdAt).toLocaleString():'—'}</td></tr>{:else}<tr><td colspan="3" class="empty">Queue is empty.</td></tr>{/each}</tbody></table></div>
  {:else}
    <section class="settings"><article class="github-settings"><div class="settings-head"><div><p class="kicker">GITHUB CONNECTION</p><h2>GitHub account</h2><p>A fine-grained personal access token discovers only the repositories you allow and keeps private repository access read-only.</p></div><a class="primary oauth" href={state.config.githubAccounts.length?'https://github.com/settings/personal-access-tokens':'https://github.com/settings/personal-access-tokens/new'} target="_blank" rel="noreferrer">{state.config.githubAccounts.length?'Manage GitHub tokens':'Create GitHub token'}</a></div><div class="oauth-config"><label>Fine-grained personal access token<input type="password" autocomplete="off" bind:value={githubToken} placeholder="github_pat_…" on:keydown={(event)=>event.key==='Enter'&&connectGitHub()}/><small>Select the repositories X may access and grant Metadata: Read-only and Contents: Read-only. To change an existing token, open Manage GitHub tokens and select that token by name.</small></label><button disabled={connectingGitHub} on:click={connectGitHub}>{connectingGitHub?'Checking…':'Connect'}</button></div><div class="accounts"><h3>Connected accounts</h3>{#each state.config.githubAccounts as account}<div class="account"><span><b>{account.login}</b><small>{account.type==='pat'?'GitHub fine-grained token':'GitHub OAuth'}</small></span><button on:click={()=>run(()=>api('settings',{method:'PUT',body:JSON.stringify({removeAccountId:account.id})}))}>Disconnect</button></div>{:else}<p>No GitHub account connected.</p>{/each}</div></article><article><h2>Home Assistant notifications</h2><p>Choose which events trigger a notification and who receives it.</p><h3>Events</h3><div class="toggles"><label><input type="checkbox" bind:checked={state.config.notifications.applicationErrors}/> Application install and runtime errors</label><label><input type="checkbox" bind:checked={state.config.notifications.applicationStopped}/> Applications that exit unexpectedly</label><label><input type="checkbox" bind:checked={state.config.notifications.repositoryErrors}/> Repository scan and Git pull errors</label><label><input type="checkbox" bind:checked={state.config.notifications.integrationErrors}/> Integration install and update errors</label><label><input type="checkbox" bind:checked={state.config.notifications.updatesAvailable}/> Available update notifications</label><label><input type="checkbox" bind:checked={state.config.notifications.successfulUpdates}/> Successful integration updates</label></div><h3>Recipients</h3><div class="recipients"><label><input type="checkbox" bind:checked={state.config.notifications.persistentNotification}/><span><b>Home Assistant</b><small>persistent_notification</small></span></label>{#each haNotifications.notifyServices as service}<label><input type="checkbox" checked={(state.config.notifications.notifyServices||[]).includes(service)} on:change={()=>toggleService(service)}/><span><b>{service.replaceAll('_',' ')}</b><small>notify.{service}</small></span></label>{/each}{#if !haNotifications.connected}<p>Notify services become available when the add-on is running inside Home Assistant.</p>{:else if !haNotifications.notifyServices.length}<p>No notify services were found in Home Assistant.</p>{/if}</div><button class="primary" on:click={saveNotifications}>Save notification preferences</button></article></section>
  {/if}
  {#if view==='settings'}<section class="settings update-settings"><article><h2>Update checks</h2><p>Checks detect new versions without installing integration updates automatically.</p><div class="row"><select bind:value={state.config.updateChecks.interval}><option value={2592000}>Monthly</option><option value={604800}>Weekly</option><option value={86400}>Daily</option><option value={43200}>Every 12 hours</option><option value={3600}>Hourly</option><option value={1800}>Every 30 minutes</option></select><button class="primary" on:click={saveUpdateInterval}>Save interval</button></div><small>Last check: {state.config.updateChecks.lastCheck?new Date(state.config.updateChecks.lastCheck).toLocaleString():'Not checked yet'}</small></article></section>{/if}
{#if repoDialog}<div class="modal-backdrop" role="presentation" on:click={(event)=>event.currentTarget===event.target&&(repoDialog=false)}><section class="repo-modal"><header><div><p class="kicker">REPOSITORY</p><h2>Add repository</h2></div><button on:click={()=>repoDialog=false}>×</button></header><label>Repository type<select bind:value={repoMode}><option value="public">Public</option><option value="private">Private / GitHub account</option></select></label>{#if repoMode==='public'}<div class="repo-form"><h3>Add any public repository</h3><p>No GitHub login is required.</p><div class="row"><input bind:value={publicRepository} placeholder="owner/repository"/><button class="primary" on:click={()=>addRepo(publicRepository,'')}>Add</button></div></div>{:else}<div class="repo-form"><h3>Add from your GitHub account</h3><p>Choose a repository available to a connected account.</p><div class="row account-load"><label>GitHub account<select bind:value={accountId} on:change={loadRepos}><option value="">Choose account</option>{#each state.config.githubAccounts as account}<option value={account.id}>{account.login}</option>{/each}</select></label><button disabled={loadingRepos||!accountId} on:click={loadRepos}>{loadingRepos?'Loading…':'Load'}</button></div>{#if repoLoadMessage}<p class="repo-load-message">{repoLoadMessage}</p>{/if}<div class="row"><select bind:value={repository} disabled={loadingRepos||!githubRepos.length}><option value="">Choose repository…</option>{#each githubRepos as repo}<option value={repo.fullName}>{repo.fullName}{repo.private?' · private':''}</option>{/each}</select><button class="primary" disabled={!repository} on:click={()=>addRepo()}>Add</button></div></div>{/if}<button class="cancel" on:click={()=>repoDialog=false}>Cancel</button></section></div>{/if}
<style>
  h2{font-size:14px;margin:28px 0 10px}.table{border:1px solid #282f39;border-radius:8px;overflow:auto;background:#0e1319}table{width:100%;border-collapse:collapse;min-width:650px}th{text-align:left;color:#798493;font-size:10px;text-transform:uppercase;letter-spacing:.08em;padding:10px 13px;border-bottom:1px solid #282f39}td{padding:12px 13px;border-bottom:1px solid #202630;color:#aeb6c2}tr:last-child td{border-bottom:0}tbody tr{cursor:pointer}tbody tr:hover{background:#151b23}td b{display:block;color:#edf0f4}td small{display:block;color:#788391;margin-top:3px;max-width:500px}.empty{text-align:center;padding:34px}.toolbar,.row{display:flex;gap:8px;align-items:center;margin-bottom:14px}.toolbar select{max-width:280px}.flash{padding:9px 12px;background:#123328;color:#78e4ba;border:1px solid #275944;border-radius:6px;margin-bottom:12px}.flash.bad{background:#35171b;color:#f39ba5;border-color:#633039}.ok{color:#47e0a4}.danger,.metric-danger b{color:#ff7788!important}.hero{position:relative;overflow:hidden;border:1px solid #2a333d;border-radius:14px;padding:clamp(24px,5vw,48px);background:linear-gradient(125deg,#101922,#10141b);display:flex;align-items:center;justify-content:space-between;min-height:230px}.hero h2{font-size:clamp(25px,4vw,44px);letter-spacing:-.04em;max-width:680px;margin:5px 0 12px}.hero p{color:#9aa6b3;max-width:650px;line-height:1.6}.kicker{color:#45dda3!important;font-size:10px;font-weight:800;letter-spacing:.16em}.dashboard-hero>span{padding:8px 11px;border:1px solid #285d4b;background:#123026;color:#65e6b6;border-radius:99px}.discover-hero{background:radial-gradient(circle at 85% 45%,#214e48 0,transparent 32%),linear-gradient(120deg,#111922,#161323)}.orb{flex:0 0 150px;height:150px;border-radius:38%;display:grid;place-items:center;background:linear-gradient(145deg,#57e7b0,#278ccf);color:#071510;font-size:70px;font-weight:950;transform:rotate(8deg);box-shadow:0 20px 70px #42d7aa30}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;ma